// SPAKE2 against vectors from the Rust implementation (`farwing_protocol::
// crypto`, generated by crates/protocol/examples/pake_vectors.rs): the
// browser side with a fixed scalar, the host side as Rust produced it.
import { describe, expect, test } from 'vitest';
import { b64, unb64, utf8 } from '../lib/encoding';
import { ASSIST_PAKE_IDENTITY, keyConfirm, keyConfirmMatches, pakeBinding, pakeStart, Spake2 } from '../lib/spake2';

const L = 7237005577332262213973186563042994240857116359379907606001950938285454250989n;
const XY = 0x0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdefn % L;
const BROWSER = 'U4RCiD16QgoSMF34IPdk6PYCBsia85_hIh_OJpMPmv5p';
const HOST = 'U8Kq0pVhBFX6QktIjZNGSzxYbpJ8oK4xRCupkwHY8WKI';
const KEY = 'OVob4vdKGQYucySrjvB4H8Wxedt2WKtLRTQWYJGg-2U';
const WRONG_HOST = 'U3eEVMTB5_dZch_5KEY4O9w3Sws3cJisdJ_Qy3txxq-s';
const WRONG_KEY = 'UJ-ZuIUHtZGdwkHc2SnzUuzRgHeEEvY2bvEOUoEHeGE';

describe('spake2', () => {
  test('browser message for a fixed scalar', () => {
    expect(b64(new Spake2(utf8('482913'), ASSIST_PAKE_IDENTITY, XY).message)).toBe(BROWSER);
  });

  test('same key as the Rust host', () => {
    const state = new Spake2(utf8('482913'), ASSIST_PAKE_IDENTITY, XY);
    expect(b64(state.finish(unb64(HOST)))).toBe(KEY);
  });

  test('a host with another code derives another key', () => {
    const state = new Spake2(utf8('482913'), ASSIST_PAKE_IDENTITY, XY);
    const key = state.finish(unb64(WRONG_HOST));
    expect(b64(key)).not.toBe(KEY);
    // The Rust host with the wrong code got this key; ours differs, so key
    // confirmation fails.
    expect(b64(key)).not.toBe(WRONG_KEY);
  });

  test('key confirmation and DTLS binding match Rust', () => {
    const key = unb64(KEY);
    expect(keyConfirm(key, 'host', 'rid-1')).toBe('7QMHMxmjXSMCjVbFGmKfNxX1o-KDYa9WaZhYSuPD2CY');
    expect(keyConfirm(key, 'controller', 'rid-1')).toBe('64AYAvNLlklaABAnl55zhHYoWoEx1VHvueOje6iahfY');
    expect(keyConfirmMatches(key, 'host', 'rid-1', '7QMHMxmjXSMCjVbFGmKfNxX1o-KDYa9WaZhYSuPD2CY')).toBe(true);
    expect(keyConfirmMatches(key, 'host', 'rid-2', '7QMHMxmjXSMCjVbFGmKfNxX1o-KDYa9WaZhYSuPD2CY')).toBe(false);
    expect(pakeBinding(key, 'sid-1', 'controller', ['sha-256 01:02:03', 'sha-256 aa:bb:cc'])).toBe(
      's_mT6uIBV6pxxMfldrugsckkBGVxGRnGWeF7qI11n2I',
    );
  });

  test('two browser instances agree with each other', () => {
    const a = pakeStart('code-1');
    const b = pakeStart('code-1');
    const c = pakeStart('code-2');
    expect(b64(a.state.finish(unb64(b.message)))).toBe(b64(b.state.finish(unb64(a.message))));
    const d = pakeStart('code-1');
    expect(b64(d.state.finish(unb64(c.message)))).not.toBe(b64(c.state.finish(unb64(d.message))));
  });

  test('rejects malformed messages', () => {
    const { state } = pakeStart('x');
    expect(() => state.finish(new Uint8Array(32))).toThrow();
    const wrongSide = unb64(HOST);
    wrongSide[0] = 0x41;
    expect(() => state.finish(wrongSide)).toThrow();
  });
});
